import { C, INTERNAL, LogCallback, ParseCallback, Point, Range, SIZE_OF_INT, SIZE_OF_RANGE, setModule } from './constants';
import { Language } from './language';
import { marshalRange, unmarshalRange } from './marshal';
import { checkModule, initializeBinding } from './bindings';
import type { ModuleOptions } from './wasi-module';
import { Tree } from './tree';
import { TextBuffer, textBufferByteLength } from './text_buffer';
import { newFinalizer } from './finalization_registry';

/**
 * Options for parsing
 *
 * The `includedRanges` property is an array of {@link Range} objects that
 * represent the ranges of text that the parser should include when parsing.
 *
 * The `progressCallback` property is a function that is called periodically
 * during parsing to check whether parsing should be cancelled.
 *
 * See {@link Parser#parse} for more information.
 */
export interface ParseOptions {
  /**
   * An array of {@link Range} objects that
   * represent the ranges of text that the parser should include when parsing.
   *
   * This sets the ranges of text that the parser should include when parsing.
   * By default, the parser will always include entire documents. This
   * function allows you to parse only a *portion* of a document but
   * still return a syntax tree whose ranges match up with the document
   * as a whole. You can also pass multiple disjoint ranges.
   * If `ranges` is empty, then the entire document will be parsed.
   * Otherwise, the given ranges must be ordered from earliest to latest
   * in the document, and they must not overlap. That is, the following
   * must hold for all `i` < `length - 1`:
   * ```text
   *     ranges[i].end_byte <= ranges[i + 1].start_byte
   * ```
   */
  includedRanges?: Range[];

  /**
   * A function that is called periodically during parsing to check
   * whether parsing should be cancelled. If the progress callback returns
   * `true`, then parsing will be cancelled. You can also use this to instrument
   * parsing and check where the parser is at in the document. The progress callback
   * takes a single argument, which is a {@link ParseState} representing the current
   * state of the parser.
   */
  progressCallback?: (state: ParseState) => void;
}

/**
 * A stateful object that is passed into the progress callback {@link ParseOptions#progressCallback}
 * to provide the current state of the parser.
 */
export interface ParseState {
  /** The byte offset in the document that the parser is at. */
  currentOffset: number;

  /** Indicates whether the parser has encountered an error during parsing. */
  hasError: boolean;
}

/**
 * @internal
 *
 * Global variable for transferring data across the FFI boundary
 */
export let TRANSFER_BUFFER: number;

/**
 * The latest ABI version that is supported by the current version of the
 * library.
 *
 * When Languages are generated by the Tree-sitter CLI, they are
 * assigned an ABI version number that corresponds to the current CLI version.
 * The Tree-sitter library is generally backwards-compatible with languages
 * generated using older CLI versions, but is not forwards-compatible.
 */
export let LANGUAGE_VERSION: number;

/**
 * The earliest ABI version that is supported by the current version of the
 * library.
 */
export let MIN_COMPATIBLE_VERSION: number;

const finalizer = newFinalizer((addresses: number[]) => {
  C._ts_parser_delete(addresses[0]);
  C._free(addresses[1]);
});

function isUnsignedInteger(value: number, maximum: number): boolean {
  return Number.isSafeInteger(value) && value >= 0 && value <= maximum;
}

function validateIncludedRanges(ranges: Range[]): void {
  if (ranges.length > Math.floor(0xffffffff / SIZE_OF_RANGE)) throw new RangeError('Too many included ranges');
  let previousIndex = 0;
  let previousPosition = { row: 0, column: 0 };
  for (const range of ranges) {
    const { startIndex, endIndex, startPosition, endPosition } = range;
    if (!isUnsignedInteger(startIndex, 0x7fffffff) || !isUnsignedInteger(endIndex, 0x7fffffff)
      || !isUnsignedInteger(startPosition.row, 0xffffffff) || !isUnsignedInteger(endPosition.row, 0xffffffff)
      || !isUnsignedInteger(startPosition.column, 0x7fffffff) || !isUnsignedInteger(endPosition.column, 0x7fffffff)
      || startIndex < previousIndex || endIndex < startIndex
      || positionBefore(startPosition, previousPosition) || positionBefore(endPosition, startPosition)) {
      throw new RangeError('Invalid included ranges');
    }
    previousIndex = endIndex;
    previousPosition = endPosition;
  }
}

function positionBefore(left: Range['startPosition'], right: Range['startPosition']): boolean {
  return left.row < right.row || (left.row === right.row && left.column < right.column);
}

/**
 * A stateful object that is used to produce a {@link Tree} based on some
 * source code.
 */
export class Parser {
  /** @internal */
  private [0] = 0; // Internal handle for Wasm

  /** @internal */
  private [1] = 0; // Internal handle for Wasm

  /** @internal */
  private logCallback: LogCallback | null = null;

  /** The parser's current language. */
  language: Language | null = null;

  /**
   * This must always be called before creating a Parser.
   *
   * You can optionally pass in options to configure the Wasm module, the most common
   * one being `locateFile` to help the module find the `.wasm` file.
   */
  static async init(moduleOptions?: ModuleOptions) {
    setModule(await initializeBinding(moduleOptions));
    TRANSFER_BUFFER = C._ts_init();
    LANGUAGE_VERSION = C.getValue(TRANSFER_BUFFER, 'i32');
    MIN_COMPATIBLE_VERSION = C.getValue(TRANSFER_BUFFER + SIZE_OF_INT, 'i32');
  }

  /**
   * Create a new parser.
   */
  constructor() {
    this.initialize();
    finalizer?.register(this, [this[0], this[1]], this);
  }

  /** @internal */
  initialize() {
    if (!checkModule()) {
      throw new Error("cannot construct a Parser before calling `init()`");
    }
    C._ts_parser_new_wasm();
    this[0] = C.getValue(TRANSFER_BUFFER, 'i32');
    this[1] = C.getValue(TRANSFER_BUFFER + SIZE_OF_INT, 'i32');
  }

  /** Delete the parser, freeing its resources. */
  delete() {
    finalizer?.unregister(this);
    C._ts_parser_delete(this[0]);
    C._free(this[1]);
    this[0] = 0;
    this[1] = 0;
  }

  /**
   * Set the language that the parser should use for parsing.
   *
   * If the language was not successfully assigned, an error will be thrown.
   * This happens if the language was generated with an incompatible
   * version of the Tree-sitter CLI. Check the language's version using
   * {@link Language#version} and compare it to this library's
   * {@link LANGUAGE_VERSION} and {@link MIN_COMPATIBLE_VERSION} constants.
   */
  setLanguage(language: Language | null): this {
    let address: number;
    if (!language) {
      address = 0;
      this.language = null;
    } else if (language.constructor === Language) {
      address = language[0];
      const version = C._ts_language_abi_version(address);
      if (version < MIN_COMPATIBLE_VERSION || LANGUAGE_VERSION < version) {
        throw new Error(
          `Incompatible language version ${version}. ` +
          `Compatibility range ${MIN_COMPATIBLE_VERSION} through ${LANGUAGE_VERSION}.`
        );
      }
      this.language = language;
    } else {
      throw new Error('Argument must be a Language');
    }

    C._ts_parser_set_language(this[0], address);
    return this;
  }

  /**
   * Parse a slice of UTF8 text.
   *
   * @param {string | ParseCallback | TextBuffer} callback - The text to parse, a callback function, or a
   *   {@link TextBuffer}, which is read in place.
   *
   * @param {Tree | null} [oldTree] - A previous syntax tree parsed from the same document. If the text of the
   *   document has changed since `oldTree` was created, then you must edit `oldTree` to match
   *   the new text using {@link Tree#edit}.
   *
   * @param {ParseOptions} [options] - Options for parsing the text.
   *  This can be used to set the included ranges, or a progress callback.
   *
   * @returns {Tree | null} A {@link Tree} if parsing succeeded, or `null` if:
   *  - The parser has not yet had a language assigned with {@link Parser#setLanguage}.
   *  - The progress callback returned true.
   * @throws {RangeError} If included ranges have invalid coordinates, are reversed, or overlap.
   */
  parse(
    callback: string | ParseCallback | TextBuffer,
    oldTree?: Tree | null,
    options?: ParseOptions,
  ): Tree | null {
    const ranges = options?.includedRanges ?? [];
    validateIncludedRanges(ranges);
    const byteLength = callback instanceof TextBuffer ? textBufferByteLength(callback.length) : 0;
    const previousParseCallback = C.currentParseCallback;
    const previousLogCallback = C.currentLogCallback;
    const previousProgressCallback = C.currentProgressCallback;
    let rangeAddress = 0;
    try {
      if (callback instanceof TextBuffer) {
        C.currentParseCallback = callback.read;
      } else if (typeof callback === 'string') {
        C.currentParseCallback = (index: number, _position?: Point, endIndex?: number) => callback.slice(index, endIndex);
      } else if (typeof callback === 'function') {
        C.currentParseCallback = callback;
      } else {
        throw new Error('Argument must be a string or a function');
      }

      const progressCallback = options?.progressCallback ?? null;
      C.currentProgressCallback = progressCallback;

      if (this.logCallback) {
        C.currentLogCallback = this.logCallback;
        C._ts_parser_enable_logger_wasm(this[0], 1);
      } else {
        C.currentLogCallback = null;
        C._ts_parser_enable_logger_wasm(this[0], 0);
      }

      const rangeCount = ranges.length;
      rangeAddress = rangeCount ? C._calloc(rangeCount, SIZE_OF_RANGE) : 0;
      if (rangeCount && !rangeAddress) throw new Error('Failed to allocate included ranges');
      for (let i = 0; i < rangeCount; i++) {
        marshalRange(rangeAddress + i * SIZE_OF_RANGE, ranges[i]);
      }

      C.HEAP32[TRANSFER_BUFFER >>> 2] = progressCallback ? 1 : 0;

      const treeAddress = callback instanceof TextBuffer
        ? C._ts_parser_parse_utf16_wasm(
          this[0],
          callback[0],
          byteLength,
          oldTree ? oldTree[0] : 0,
          rangeAddress,
          rangeCount
        )
        : C._ts_parser_parse_wasm(
          this[0],
          this[1],
          oldTree ? oldTree[0] : 0,
          rangeAddress,
          rangeCount
        );

      if (treeAddress === -1) throw new RangeError('Invalid included ranges');
      if (!treeAddress) {
        return null;
      }

      if (!this.language) {
        throw new Error('Parser must have a language to parse');
      }

      const result = new Tree(INTERNAL, treeAddress, this.language, C.currentParseCallback);
      return result;
    } finally {
      C._free(rangeAddress);
      C.currentParseCallback = previousParseCallback;
      C.currentLogCallback = previousLogCallback;
      C.currentProgressCallback = previousProgressCallback;
    }
  }

  /**
   * Instruct the parser to start the next parse from the beginning.
   *
   * If the parser previously failed because of a callback,
   * then by default, it will resume where it left off on the
   * next call to {@link Parser#parse} or other parsing functions.
   * If you don't want to resume, and instead intend to use this parser to
   * parse some other document, you must call `reset` first.
   */
  reset(): void {
    C._ts_parser_reset(this[0]);
  }

  /** Get the ranges of text that the parser will include when parsing. */
  getIncludedRanges(): Range[] {
    C._ts_parser_included_ranges_wasm(this[0]);
    const count = C.getValue(TRANSFER_BUFFER, 'i32');
    const buffer = C.getValue(TRANSFER_BUFFER + SIZE_OF_INT, 'i32');
    const result = new Array<Range>(count);

    if (count > 0) {
      let address = buffer;
      for (let i = 0; i < count; i++) {
        result[i] = unmarshalRange(address);
        address += SIZE_OF_RANGE;
      }
      C._free(buffer);
    }

    return result;
  }

  /** Set the logging callback that a parser should use during parsing. */
  setLogger(callback: LogCallback | boolean | null): this {
    if (!callback) {
      this.logCallback = null;
    } else if (typeof callback !== 'function') {
      throw new Error('Logger callback must be a function');
    } else {
      this.logCallback = callback;
    }
    return this;
  }

  /** Get the parser's current logger. */
  getLogger(): LogCallback | null {
    return this.logCallback;
  }
}
